// ============================================================
// ORCHESTRATOR - ENTRY POINT
// Uses n8n staticData for session persistence (no fs/require)
// ============================================================
const inputData = items[0].json;
const body = inputData.body || inputData;
const userId = body.user_id || 'anonymous';
let sessionId = body.session_id;
const userMessage = body.message || '';

const staticData = $getWorkflowStaticData('global');
if (!staticData.sessions) staticData.sessions = {};

function generateUUID() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
    const r = Math.random() * 16 | 0;
    return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
  });
}

function newContext(sid, uid) {
  const now = new Date().toISOString();
  return {
    session_id: sid, user_id: uid,
    status: 'collecting_preferences', next_action: 'invoke_preference_agent',
    created_at: now, updated_at: now,
    preferences: {
      departure_date: null,
      departure_city: null,
      departure_country: null,
      trip_duration_days: null,
      number_of_members: null,
      budget: { amount: null, currency: 'USD', budget_type: 'total' },
      travel_style: null, special_requirements: []
    },
    tags: [], destination_candidates: [], recommended_destinations: [],
    final_itinerary: {}, conversation_history: [],
    agent_results: { preference_agent: null, destination_finder: null, recommender: null, planner: null },
    errors: [], retry_counts: {}
  };
}

let tripContext;
if (!sessionId) {
  sessionId = generateUUID();
  tripContext = newContext(sessionId, userId);
} else {
  tripContext = staticData.sessions[sessionId] || newContext(sessionId, userId);
}

tripContext.updated_at = new Date().toISOString();
if (userMessage) {
  tripContext.conversation_history.push({ role: 'user', content: userMessage, timestamp: new Date().toISOString() });

  // When user replies, route back to the right agent instead of staying on respond_to_user
  if (tripContext.next_action === 'respond_to_user') {
    const statusToAction = {
      'collecting_preferences': 'invoke_preference_agent',
      'finding_destinations':   'invoke_destination_finder',
      'recommending':           'invoke_recommender',
      'planning':               'invoke_planner',
    };
    tripContext.next_action = statusToAction[tripContext.status] || 'invoke_preference_agent';
  }
}

staticData.sessions[sessionId] = tripContext;
return [{ json: { tripContext, user_message: userMessage, session_id: sessionId } }];

const agentOutput = items[0].json.output || items[0].json.text || '';
const tripContext = $('Orchestrator - Init Session').item.json.tripContext;
tripContext.conversation_history.push({ role: 'assistant', content: agentOutput, timestamp: new Date().toISOString() });

const result = { agent: 'preference_agent', success: false, output_text: agentOutput, parsed_json: null, validation_errors: [] };

// ONLY try to extract preferences if the markers are present
const startMarker = '---PREFERENCES_COMPLETE---';
const endMarker = '---END_PREFERENCES---';
const hasStartMarker = agentOutput.includes(startMarker);
const hasEndMarker = agentOutput.includes(endMarker);

if (hasStartMarker && hasEndMarker) {
  const startIndex = agentOutput.indexOf(startMarker);
  const endIndex = agentOutput.indexOf(endMarker);

  if (endIndex > startIndex) {
    let jsonStart = startIndex + startMarker.length;
    while (jsonStart < agentOutput.length && (agentOutput[jsonStart] === '\n' || agentOutput[jsonStart] === '\r' || agentOutput[jsonStart] === ' ')) {
      jsonStart++;
    }

    let jsonEnd = endIndex;
    while (jsonEnd > jsonStart && (agentOutput[jsonEnd - 1] === '\n' || agentOutput[jsonEnd - 1] === '\r' || agentOutput[jsonEnd - 1] === ' ')) {
      jsonEnd--;
    }

    const jsonStr = agentOutput.substring(jsonStart, jsonEnd);

    try {
      const prefs = JSON.parse(jsonStr);

      const missing = [];

      if (!prefs.departure_date || prefs.departure_date === null || prefs.departure_date === '') {
        missing.push('departure_date');
      }

      if (!prefs.departure_city || prefs.departure_city === null || prefs.departure_city === '') {
        missing.push('departure_city');
      }

      if (!prefs.departure_country || prefs.departure_country === null || prefs.departure_country === '') {
        missing.push('departure_country');
      }

      if (!prefs.trip_duration_days || prefs.trip_duration_days === null || prefs.trip_duration_days === '') {
        missing.push('trip_duration_days');
      }

      if (!prefs.number_of_members || prefs.number_of_members === null || prefs.number_of_members === '') {
        missing.push('number_of_members');
      }

      if (!prefs.budget || prefs.budget === null || typeof prefs.budget !== 'object') {
        missing.push('budget');
      } else {
        if (!prefs.budget.amount && prefs.budget.amount !== 0) {
          missing.push('budget.amount');
        }
      }

      if (!prefs.tags || !Array.isArray(prefs.tags) || prefs.tags.length === 0) {
        missing.push('tags');
      }

      if (missing.length === 0) {
        result.success = true;
        result.parsed_json = prefs;
        const beforeMarker = agentOutput.substring(0, startIndex);
        const afterMarker = agentOutput.substring(endIndex + endMarker.length);
        result.output_text = (beforeMarker + afterMarker).trim() || 'All preferences collected. Searching for destinations...';
      } else {
        result.validation_errors = missing;
        result.output_text = agentOutput;
      }

    } catch(e) {
      result.validation_errors = ['JSON parse error: ' + e.message];
      console.error('Parse error:', e.message);
      console.error('JSON string:', jsonStr.substring(0, 500));
    }
  } else {
    result.validation_errors = ['End marker appears before start marker'];
  }
}

tripContext.agent_results.preference_agent = result;
tripContext.updated_at = new Date().toISOString();

console.log('Agent output length:', agentOutput.length);
console.log('Has start marker:', hasStartMarker);
console.log('Has end marker:', hasEndMarker);

if (hasStartMarker) {
  const startIdx = agentOutput.indexOf(startMarker);
  console.log('Marker found at position:', startIdx);
  console.log('Next 100 chars:', agentOutput.substring(startIdx, startIdx + 100));
}

return [{ json: { tripContext, agent_result: result } }];

const tripContext = items[0].json.tripContext;
const tags = tripContext.tags || [], prefs = tripContext.preferences || {};
const sortedTags = [...tags].sort((a, b) => (b.weight || 0) - (a.weight || 0));
const queryParts = [];
for (const t of sortedTags) {
  const r = Math.max(1, Math.round((t.weight || 0.5) * 3));
  for (let i = 0; i < r; i++) queryParts.push(t.tag || '');
}
if (prefs.travel_style) queryParts.push(prefs.travel_style);
for (const req of (prefs.special_requirements || [])) queryParts.push(req);

const queryText = queryParts.join(' ').trim() || 'travel destination vacation';
const budget = prefs.budget || {}, amount = budget.amount || 0;
const days = prefs.trip_duration_days || 7, members = prefs.number_of_members || 1;
const dailyPerPersonBudget = budget.budget_type === 'per_person'
  ? amount / Math.max(days, 1)
  : amount / Math.max(days * members, 1);

const payload = {
  session_id: tripContext.session_id, query: queryText, tags,
  top_k: 30, final_k: 20, daily_per_person_budget: dailyPerPersonBudget,
  departure_date: prefs.departure_date,
  departure_city: prefs.departure_city,
  departure_country: prefs.departure_country,
  duration_days: days, members
};
return [{ json: { tripContext, rag_payload: payload, rag_payload_json: JSON.stringify(payload) } }];

const llmOutput = items[0].json;
const tripContext = $('Build RAG Payload').item.json.tripContext;
const result = { agent: 'destination_finder', success: false, candidates: [], errors: [] };

try {
  // Agent node returns output in json.output
  const rawText = (llmOutput.output || JSON.stringify(llmOutput)).trim();
  const cleaned = rawText.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
  const parsed = JSON.parse(cleaned);
  const candidates = parsed.top_10_candidates || parsed.candidates || (Array.isArray(parsed) ? parsed : []);
  if (!Array.isArray(candidates) || candidates.length < 1) {
    result.errors.push('LLM returned no candidates');
  } else {
    result.success = true;
    result.candidates = candidates.slice(0, 10);
    result.selection_summary = parsed.selection_summary || '';
    result.total_retrieved = candidates.length;
  }
} catch(e) {
  result.errors.push('LLM parse error: ' + e.message + ' | raw: ' + JSON.stringify(llmOutput).slice(0, 300));
}

tripContext.agent_results.destination_finder = result;
if (result.success) tripContext.destination_candidates = result.candidates;
tripContext.updated_at = new Date().toISOString();
return [{ json: { tripContext, agent_result: result } }];

const tripContext = items[0].json.tripContext;
const candidates = (tripContext.destination_candidates || []).slice(0, 10);
const payload = {
  session_id: tripContext.session_id,
  cities: candidates.map(c => ({
    city_name: c.city_name, country: c.country,
    lat: (c.coordinates || {}).lat || 0, lng: (c.coordinates || {}).lng || 0,
    rank: c.rank || 0, combined_score: c.combined_score || 0,
    estimated_total_cost: c.estimated_total_cost || 0, avg_daily_cost_usd: c.avg_daily_cost_usd || 0
  })),
  tags: tripContext.tags || [], top_pois_per_city: 15, final_cities: 5
};
return [{ json: { tripContext, recommender_payload: payload, recommender_payload_json: JSON.stringify(payload) } }];

const llmOutput = items[0].json;
const tripContext = $('Build Recommender Payload').item.json.tripContext;
const result = { agent: 'recommender', success: false, top_5_cities: [], errors: [] };

try {
  const rawText = (llmOutput.output || JSON.stringify(llmOutput)).trim();
  const cleaned = rawText.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
  const parsed = JSON.parse(cleaned);
  const top5 = parsed.top_5_cities || parsed.cities || (Array.isArray(parsed) ? parsed : []);
  const withPois = top5.filter(c => c.top_pois && c.top_pois.length > 0);
  if (withPois.length < 3) {
    result.errors.push('Only ' + withPois.length + ' cities have POIs (min 3 required)');
    result.top_5_cities = top5;
  } else {
    result.success = true;
    result.top_5_cities = top5.slice(0, 5);
  }
} catch(e) {
  result.errors.push('LLM parse error: ' + e.message);
}

tripContext.agent_results.recommender = result;
if (result.success) tripContext.recommended_destinations = result.top_5_cities;
tripContext.updated_at = new Date().toISOString();
return [{ json: { tripContext, agent_result: result } }];

const tripContext = items[0].json.tripContext;
const top3 = (tripContext.recommended_destinations || []).slice(0, 3);
const prefs = tripContext.preferences;

return top3.map(city => ({
  json: {
    tripContext,
    top3_cities: top3,
    script_type: 'weather',
    city_payload: {
      city: city.city_name,
      country: city.country || '',
      days: prefs.trip_duration_days || 7,
      departure_date: prefs.departure_date || '',
    }
  }
}));

const j = items[0].json;
const tripContext = j.tripContext;
const enrichedCities = j.enriched_cities || [];
const prefs = tripContext.preferences;

// Pick the top city (rank 1) as the itinerary target, but pass all 3 for LLM context
const topCity = enrichedCities[0] || {};
const topScraped = topCity.scraped || {};

const systemPrompt = [
  'You are an expert travel itinerary planner. Create a detailed day-by-day itinerary.',
  '',
  'RULES:',
  '1. Create a logical geographic route',
  '2. Group nearby POIs on the same day',
  '3. Consider weather - outdoor activities on good weather days',
  '4. Include meal suggestions (breakfast, lunch, dinner)',
  '5. Include travel time estimates between locations',
  '6. Account for jet lag on day 1 (lighter schedule)',
  '7. Include one free time block per day',
  '8. Respect opening hours when known',
  '9. Include estimated costs per activity',
  '10. Suggest the best hotel with justification',
  '',
  'OUTPUT FORMAT (STRICT JSON):',
  JSON.stringify({
    summary: { total_estimated_cost: 'float', cost_breakdown: { accommodation: 'float', activities: 'float', food: 'float', transport_local: 'float', miscellaneous: 'float' }, recommended_hotel: { name: 'string', justification: 'string', total_price: 'float' }, packing_suggestions: ['array'], travel_tips: ['3-5 tips'] },
    days: [{ day_number: 1, date: 'YYYY-MM-DD', day_label: 'Monday', theme: 'string', weather: { condition: 'string', temp_high: 'float', temp_low: 'float' }, morning: { time_slot: '09:00 - 12:00', activities: [{ name: '...', type: 'poi|meal|transport|free_time', description: '...', location: '...', estimated_duration_hours: 'float', estimated_cost: 'float', tips: '...' }] }, afternoon: { time_slot: '13:00 - 17:00', activities: [] }, evening: { time_slot: '18:00 - 22:00', activities: [] }, day_total_estimated_cost: 'float', walking_distance_km: 'float', notes: '...' }]
  }, null, 2),
  '',
  'IMPORTANT: Output ONLY valid JSON. No markdown, no explanation, just the JSON object.'
].join('\n');

const budget = prefs.budget || {};
const userContent = [
  'Primary destination: ' + topCity.city_name + ', ' + (topCity.country || ''),
  'Trip duration: ' + prefs.trip_duration_days + ' days',
  'Number of travelers: ' + prefs.number_of_members,
  'Budget: ' + budget.amount + ' ' + budget.currency + ' (' + budget.budget_type + ')',
  'Departure date: ' + prefs.departure_date,
  'Special requirements: ' + JSON.stringify(prefs.special_requirements || []),
  '',
  'POIs from recommender: ' + JSON.stringify((topCity.top_pois || []).slice(0, 12)),
  'Scraped attractions: ' + JSON.stringify((topScraped.attractions || []).slice(0, 10)),
  'Weather forecast: ' + JSON.stringify(topScraped.weather || []),
  'Recommended hotels: ' + JSON.stringify(topScraped.hotels || []),
  'User tags/preferences: ' + JSON.stringify(tripContext.tags || []),
  '',
  'Context - other top cities considered (with their data):',
  JSON.stringify(enrichedCities.slice(1).map(c => ({
    city_name: c.city_name,
    country: c.country,
    combined_score: c.combined_score,
    weather_summary: (c.scraped.weather || []).slice(0, 2),
    hotel_count: (c.scraped.hotels || []).length,
    attraction_count: (c.scraped.attractions || []).length
  })))
].join('\n');

return [{ json: { tripContext, top_city: topCity, system_prompt: systemPrompt, user_prompt: userContent } }];

function generateUUID() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
    const r = Math.random() * 16 | 0;
    return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
  });
}

const llmOutput  = items[0].json;
const promptData = $('Build Itinerary Prompt').item.json;
const tripContext = promptData.tripContext;
const topCity    = promptData.top_city || {};
const prefs      = tripContext.preferences;
const result     = { agent: 'planner', success: false, itinerary: null, errors: [] };

const baseItinerary = {
  trip_id:       generateUUID(),
  generated_at:  new Date().toISOString(),
  destination: {
    city:        topCity.city_name,
    country:     topCity.country || '',
    coordinates: topCity.coordinates || {},
  },
  trip_details: {
    departure_date: prefs.departure_date,
    duration_days:  prefs.trip_duration_days,
    travelers:      prefs.number_of_members,
    budget:         prefs.budget,
  },
};

try {
  const rawText  = (llmOutput.output || JSON.stringify(llmOutput)).trim();
  const cleaned  = rawText.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
  const itinData = JSON.parse(cleaned);
  if (!itinData.summary || !itinData.days) {
    result.errors.push('Itinerary missing required keys (summary, days)');
  } else if (!Array.isArray(itinData.days) || !itinData.days.length) {
    result.errors.push('Days array is empty or invalid');
  } else {
    result.success   = true;
    result.itinerary = { ...baseItinerary, summary: itinData.summary, days: itinData.days };
  }
} catch(e) {
  result.errors.push('Parse error: ' + e.message);
  // Avoid re-scraping loop: mark success with raw output so pipeline advances
  result.success   = true;
  result.itinerary = { ...baseItinerary, raw_output: (llmOutput.output || '').slice(0, 5000), parse_error: e.message };
}

tripContext.agent_results.planner = result;
if (result.success) tripContext.final_itinerary = result.itinerary;
tripContext.updated_at = new Date().toISOString();
return [{ json: { tripContext, agent_result: result } }];

// ============================================================
// ORCHESTRATOR - UPDATE & DECIDE NEXT STEP
// Uses n8n staticData for persistence (no fs/require)
// ============================================================
const MAX_RETRIES = 2;
const j = items[0].json, tripContext = j.tripContext, agentResult = j.agent_result, agentName = agentResult.agent;

if (!tripContext.retry_counts) tripContext.retry_counts = {};
if (!tripContext.retry_counts[agentName]) tripContext.retry_counts[agentName] = 0;

let responseMessage = '';

if (agentResult.success) {
  tripContext.retry_counts[agentName] = 0;
  if (agentName === 'preference_agent') {
    const p = agentResult.parsed_json;
    tripContext.preferences = {
      departure_date: p.departure_date,
      departure_city: p.departure_city,
      departure_country: p.departure_country,
      trip_duration_days: parseInt(p.trip_duration_days),
      number_of_members: parseInt(p.number_of_members),
      budget: p.budget,
      travel_style: p.travel_style || 'balanced',
      special_requirements: p.special_requirements || []
    };
    tripContext.tags = p.tags;
    tripContext.status = 'finding_destinations';
    tripContext.next_action = 'invoke_destination_finder';
    responseMessage = agentResult.output_text;
  } else if (agentName === 'destination_finder') {
    tripContext.status = 'recommending';
    tripContext.next_action = 'invoke_recommender';
    responseMessage = 'Found ' + tripContext.destination_candidates.length + ' top destinations. Now scoring points of interest...';
  } else if (agentName === 'recommender') {
    const top1 = tripContext.recommended_destinations[0];
    tripContext.status = 'planning';
    tripContext.next_action = 'invoke_planner';
    responseMessage = 'Top 5 destinations identified. Building itinerary for #1: ' + top1.city_name + ', ' + (top1.country || '') + '...';
  } else if (agentName === 'planner') {
    tripContext.status = 'complete';
    tripContext.next_action = 'respond_to_user';
    const itin = tripContext.final_itinerary;
    responseMessage = 'Your ' + itin.trip_details.duration_days + '-day itinerary for ' + itin.destination.city + ', ' + itin.destination.country + ' is ready!';
  }
} else {
  tripContext.retry_counts[agentName]++;
  tripContext.errors.push({ agent: agentName, errors: agentResult.errors || [], attempt: tripContext.retry_counts[agentName], timestamp: new Date().toISOString() });
  if (agentName === 'preference_agent') {
    tripContext.retry_counts[agentName] = 0;
    const missing = agentResult.validation_errors || [];
    responseMessage = missing.length
      ? 'I still need: ' + missing.join(', ') + '. Could you share that?'
      : (agentResult.output_text || '');
    tripContext.next_action = 'respond_to_user';
    tripContext.status = 'collecting_preferences';
  } else if (tripContext.retry_counts[agentName] < MAX_RETRIES) {
    tripContext.next_action = 'invoke_' + agentName;
    responseMessage = 'Retrying ' + agentName + ' (attempt ' + (tripContext.retry_counts[agentName] + 1) + '/' + MAX_RETRIES + ')...';
  } else {
    tripContext.status = 'error';
    tripContext.next_action = 'respond_to_user';
    responseMessage = "I'm sorry - the " + agentName + ' step failed after ' + MAX_RETRIES + ' attempts. Errors: ' + (agentResult.errors || []).slice(0, 2).join('; ');
  }
}

tripContext.updated_at = new Date().toISOString();
const staticData = $getWorkflowStaticData('global');
if (!staticData.sessions) staticData.sessions = {};
staticData.sessions[tripContext.session_id] = tripContext;

return [{ json: { tripContext, response_message: responseMessage, last_agent: agentName, last_agent_success: agentResult.success } }];

const j = items[0].json, tripContext = j.tripContext, status = tripContext.status;
const response = { session_id: tripContext.session_id, status, timestamp: tripContext.updated_at };

if (status === 'complete' && tripContext.final_itinerary && Object.keys(tripContext.final_itinerary).length) {
  const itin = tripContext.final_itinerary;
  response.type = 'itinerary'; response.message = j.response_message || 'Itinerary ready!'; response.itinerary = itin;
  response.summary = {
    destination: itin.destination.city + ', ' + itin.destination.country,
    duration: itin.trip_details.duration_days + ' days',
    total_cost: (itin.summary || {}).total_estimated_cost,
    recommended_hotel: ((itin.summary || {}).recommended_hotel || {}).name,
    days_planned: (itin.days || []).length
  };
} else if (status === 'error') {
  response.type = 'error'; response.message = j.response_message || 'An error occurred'; response.errors = (tripContext.errors || []).slice(-3);
} else if (status === 'collecting_preferences') {
  response.type = 'agent_message'; response.message = j.response_message || ''; response.next_action = 'await_user_input';
} else {
  response.type = 'progress'; response.message = j.response_message || ('Processing... (status: ' + status + ')');
  if ((tripContext.destination_candidates || []).length) {
    response.progress = { top_destinations: tripContext.destination_candidates.slice(0, 5).map(c => c.city_name) };
  }
}
return [{ json: response }];

