// This node splits into two paths:
// Path 0 → immediate ACK response to the webhook
// Path 1 → continues to Build RAG Payload (destination pipeline)
const input = items[0].json;
const tripContext = input.tripContext;
const sessionId = tripContext.session_id;

// Mark that we sent an early ack so downstream knows
tripContext._early_ack_sent = true;

const ackPayload = {
  session_id: sessionId,
  status: 'processing',
  type: 'ack',
  message: 'Your request is being processed. This may take 1-3 minutes. '
    + 'Poll GET /travel-status?session_id=' + sessionId + ' to retrieve your results.',
  poll_url: '/travel-status?session_id=' + sessionId,
  timestamp: new Date().toISOString()
};

return [
  { json: { ...ackPayload, _path: 'ack' } },
  { json: { tripContext, user_message: input.user_message, session_id: input.session_id, _path: 'pipeline' } }
];

const j = items[0].json;
return [{ json: {
  session_id: j.session_id,
  status: 'processing',
  type: 'ack',
  message: j.message,
  poll_url: j.poll_url,
  timestamp: j.timestamp
} }];

// Store final result in staticData so client can poll for it
const j = items[0].json;
const staticData = $getWorkflowStaticData('global');
if (!staticData.results) staticData.results = {};

// j is the formatted webhook response
const sessionId = j.session_id;
if (sessionId) {
  staticData.results[sessionId] = {
    ...j,
    stored_at: new Date().toISOString(),
    ready: true
  };
}

return [{ json: j }];

const query = items[0].json.query || {};
const sessionId = query.session_id || '';
const staticData = $getWorkflowStaticData('global');
const results = staticData.results || {};
const sessions = staticData.sessions || {};

if (!sessionId) {
  return [{ json: { error: 'session_id query param required', status: 400 } }];
}

if (results[sessionId] && results[sessionId].ready) {
  return [{ json: results[sessionId] }];
}

// Still processing
const session = sessions[sessionId];
return [{ json: {
  session_id: sessionId,
  status: session ? session.status : 'unknown',
  type: 'processing',
  message: 'Still processing. Please try again in 30 seconds.',
  timestamp: new Date().toISOString()
} }];

const input = items[0].json;
const tripContext = input.tripContext;
const recommenderPayload = input.recommender_payload;
const prefs = tripContext.preferences || {};

const fromCity = prefs.departure_city || 'Unknown';
const fromCountry = prefs.departure_country || '';
const departureDate = prefs.departure_date || '';

return recommenderPayload.cities.map(city => ({
  json: {
    tripContext,
    recommender_payload: recommenderPayload,
    city_payload: {
      from_city: fromCity,
      from_country: fromCountry,
      to_city: city.city_name,
      to_country: city.country,
      date: departureDate,
      serpapi_key: ''
    }
  }
}));

// items[] now has one entry per city (all HTTP responses collected)
// Reassemble into a single object keyed by city_name
const flightsByCity = {};
let tripContext = null;
let recommenderPayload = null;

for (const item of items) {
  const j = item.json;
  // grab context from first valid item
  if (!tripContext && j.tripContext) {
    tripContext = j.tripContext;
    recommenderPayload = j.recommender_payload;
  }
  // city_payload.to_city is the canonical key set in Split Cities for Flights
  const cityName = (j.city_payload || {}).to_city || (j.city_payload || {}).city_name || 'unknown';
  // flight response may be nested under flights / flight_options or be the whole body
  const flightData = j.flights || j.flight_options || j.data || j;
  flightsByCity[cityName] = flightData;
}

// Attach flights map to the recommender payload
if (recommenderPayload) {
  recommenderPayload.flights_data = flightsByCity;
}

// Summarise flight availability for the prompt
const flightSummaryLines = [];
for (const [city, fd] of Object.entries(flightsByCity)) {
  const hasFlights = fd && (
    (Array.isArray(fd.flights) && fd.flights.length > 0) ||
    (Array.isArray(fd.flight_options) && fd.flight_options.length > 0) ||
    (Array.isArray(fd.results) && fd.results.length > 0) ||
    (fd.best_flight != null)
  );
  if (hasFlights) {
    const firstFlight = (fd.flights || fd.flight_options || fd.results || [])[0] || fd.best_flight || {};
    const price = firstFlight.price || firstFlight.total_price || firstFlight.cost || 'N/A';
    flightSummaryLines.push(`- ${city}: FLIGHTS AVAILABLE (lowest price seen: ${price})`);
  } else {
    flightSummaryLines.push(`- ${city}: NO FLIGHTS FOUND — do not recommend this city`);
  }
}

const flightSummary = flightSummaryLines.length > 0
  ? flightSummaryLines.join('\n')
  : 'No flight data was returned — proceed with destination ranking based on other criteria.';

const enrichedText = 'Recommender Payload:\n' + JSON.stringify(recommenderPayload)
  + '\n\nFlight Availability Summary:\n' + flightSummary
  + '\n\nFull flight data per city (keyed by city_name):\n' + JSON.stringify(flightsByCity)
  + '\n\nPlease select top 5 cities and generate 15 POIs per city. Return structured JSON.';

return [{ json: { tripContext, recommender_payload: recommenderPayload, enriched_prompt: enrichedText } }];

const buildItems = $('Build Planner Payload').all();
const cityPayloads = buildItems.map(i => ({
  city:    i.json.city_payload?.city    || '',
  country: i.json.city_payload?.country || '',
}));

const weatherResults = items.map((item, idx) => ({
  city: cityPayloads[idx]?.city
    || item.json.city
    || item.json.weather?.location?.name
    || '',
  country: cityPayloads[idx]?.country
    || item.json.country
    || item.json.weather?.location?.country
    || '',
  weather: item.json,
}));

const tripContext = buildItems[0]?.json?.tripContext || {};
const prefs = tripContext.preferences || {};

const checkIn  = prefs.departure_date || '';
const duration = prefs.trip_duration_days || 7;
const checkOut = checkIn
  ? new Date(new Date(checkIn).getTime() + duration * 86400000)
      .toISOString().split('T')[0]
  : '';

const top3 = (tripContext.recommended_destinations || []).length > 0
  ? tripContext.recommended_destinations.slice(0, 3)
  : weatherResults.map(r => ({ city_name: r.city, country: r.country }));

const batchRequests = [];
for (const city of top3) {
  batchRequests.push({
    type:      'hotels',
    city:      city.city_name,
    country:   city.country || '',
    check_in:  checkIn,
    check_out: checkOut,
  });
  batchRequests.push({
    type:    'attractions',
    city:    city.city_name,
    country: city.country || '',
    date:    checkIn,
  });
}

return [{ json: { tripContext, weather_results: weatherResults, batch_payload: { requests: batchRequests } } }];

const searchResult = items[0].json.result || items[0].json || {};
const collectData  = $('Collect All Planner Data').first().json;
const tripContext  = collectData.tripContext || {};
const weatherResults = collectData.weather_results || [];

// Safely coerce any value to an array regardless of backend response shape
function toArr(val) {
  if (!val) return [];
  if (Array.isArray(val)) return val;
  if (Array.isArray(val.forecast))    return val.forecast;
  if (Array.isArray(val.weather))     return val.weather;
  if (Array.isArray(val.data))        return val.data;
  if (Array.isArray(val.results))     return val.results;
  if (Array.isArray(val.hotels))      return val.hotels;
  if (Array.isArray(val.attractions)) return val.attractions;
  return [];
}

// Index weather by lowercased city name for fast lookup
const weatherByCity = {};
for (const w of weatherResults) {
  if (w.city) weatherByCity[w.city.toLowerCase()] = w;
}

// Hotels/attractions may be nested under various keys
const hotelsMap      = searchResult.hotels      || searchResult.hotel      || {};
const attractionsMap = searchResult.attractions  || searchResult.attraction  || {};

// Build enriched cities, preserving city_name + country from recommended_destinations
const top3 = (tripContext.recommended_destinations || []).slice(0, 3);

const enrichedCities = top3.map((city, idx) => {
  const key      = (city.city_name || '').toLowerCase();
  const wEntry   = weatherByCity[key] || weatherResults[idx] || {};
  const hotels   = hotelsMap[city.city_name] || hotelsMap[key] || [];
  const attracts = attractionsMap[city.city_name] || attractionsMap[key] || [];

  return {
    city_name:      city.city_name,
    country:        city.country || '',
    combined_score: city.combined_score || 0,
    coordinates:    city.coordinates || {},
    top_pois:       city.top_pois || [],
    scraped: {
      weather:     toArr(wEntry.weather?.forecast ?? wEntry.weather ?? wEntry.weather_data ?? wEntry),
      hotels:      toArr(hotels),
      attractions: toArr(attracts),
    },
  };
});

tripContext.planner_data = {
  weather:     weatherResults,
  hotels:      hotelsMap,
  attractions: attractionsMap,
};

return [{ json: { tripContext, enriched_cities: enrichedCities } }];
